&lt;li&gt;&lt;span class=&quot;TextRun SCXW57822247 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW57822247 BCX0&quot; data-ccp-parastyle=&quot;List Bullet&quot;&gt;You’re&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW57822247 BCX0&quot; data-ccp-parastyle=&quot;List Bullet&quot;&gt;&amp;nbsp;a systems thinker who sees the connections between an engineering release, a long-lead procurement, a production schedule, and a field delivery date — and you manage the dependencies across all of them&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW57822247 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;EOP SCXW57822247 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&lt;span class=&quot;TextRun SCXW7749108 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW7749108 BCX0&quot; data-ccp-parastyle=&quot;List Bullet&quot;&gt;You’re&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW7749108 BCX0&quot; data-ccp-parastyle=&quot;List Bullet&quot;&gt;&amp;nbsp;highly autonomous — you&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW7749108 BCX0&quot; data-ccp-parastyle=&quot;List Bullet&quot;&gt;don’t&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW7749108 BCX0&quot; data-ccp-parastyle=&quot;List Bullet&quot;&gt;&amp;nbsp;wait to be told&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW7749108 BCX0&quot; data-ccp-parastyle=&quot;List Bullet&quot;&gt;what’s&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW7749108 BCX0&quot; data-ccp-parastyle=&quot;List Bullet&quot;&gt;&amp;nbsp;broken; you find the constraint, build the fix, and brief leadership on the outcome&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW7749108 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;EOP SCXW57822247 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&lt;span class=&quot;EOP SCXW7749108 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&lt;span class=&quot;TextRun SCXW34050197 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW34050197 BCX0&quot; data-ccp-parastyle=&quot;List Bullet&quot;&gt;You have exceptional analytical skills with the ability to model complex production and supply chain data sets and translate them into actionable plans and forecasts&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW34050197 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;EOP SCXW57822247 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&lt;span class=&quot;EOP SCXW7749108 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&lt;span class=&quot;EOP SCXW34050197 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&lt;span class=&quot;TextRun SCXW44419362 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW44419362 BCX0&quot; data-ccp-parastyle=&quot;List Bullet&quot;&gt;You’re&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW44419362 BCX0&quot; data-ccp-parastyle=&quot;List Bullet&quot;&gt;&amp;nbsp;comfortable operating across organizational boundaries, driving alignment between engineering, manufacturing, procurement, and quality teams that&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW44419362 BCX0&quot; data-ccp-parastyle=&quot;List Bullet&quot;&gt;don’t&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW44419362 BCX0&quot; data-ccp-parastyle=&quot;List Bullet&quot;&gt;&amp;nbsp;naturally talk to each other&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW44419362 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
