&lt;li class=&quot;s-break-words s-text-foreground dark:s-text-foreground-night s-text-base s-leading-relaxed&quot;&gt;AI tools (Dust)&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 class=&quot;s-pb-2 s-pt-4 s-heading-lg s-text-foreground dark:s-text-foreground-night&quot;&gt;Languages&lt;/h3&gt;
&lt;ul class=&quot;s-list-disc s-pb-2 s-pl-6 s-flex s-flex-col s-gap-1 s-text-foreground dark:s-text-foreground-night s-text-base s-leading-relaxed&quot;&gt;
&lt;li class=&quot;s-break-words s-text-foreground dark:s-text-foreground-night s-text-base s-leading-relaxed&quot;&gt;&lt;strong class=&quot;s-font-semibold s-text-foreground dark:s-text-foreground-night&quot;&gt;French&lt;/strong&gt;: Fluent&amp;nbsp;&lt;/li&gt;
